using System;using System.IO;using System.Reflection;using System.Text;
class RuntimeChecks{
 static Type runtime,stateType,optionsType;static BindingFlags s=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic,i=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static int n,asked,installed,refreshed;static object next;static bool answer;static int exit;static object Call(string name,params object[]a){try{return runtime.GetMethod(name,s).Invoke(null,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool ok,string why){if(!ok)throw new Exception(why);n++;Console.WriteLine("PASS "+why);}static void Set(object o,string k,object v){o.GetType().GetField(k,i).SetValue(o,v);}static bool Ready(object o){return (bool)stateType.GetProperty("Ready").GetValue(o,null);}static object State(string version,bool files=true){var o=Activator.CreateInstance(stateType,true);Set(o,"MsvcpX86",files);Set(o,"VcruntimeX86",files);Set(o,"UcrtX86",files);Set(o,"MsvcpVersion",version);Set(o,"VcruntimeVersion",version);return o;}static object Options(bool marker,bool dlc){var o=Activator.CreateInstance(optionsType,true);Set(o,"MarkerPatch",marker);Set(o,"Dlc",dlc);Set(o,"Chinese",true);return o;}static bool Confirm(){asked++;return answer;}static int Install(){installed++;return exit;}static object Refresh(){refreshed++;return next;}static void Reset(object after,bool yes=true,int code=0){asked=installed=refreshed=0;next=after;answer=yes;exit=code;}static bool Throws(Action a,Type expected){try{a();return false;}catch(Exception e){return expected.IsInstanceOfType(e);}}
 static object Flow(object options,bool interactive,object before){var function=typeof(RuntimeChecks).GetMethod("GetTypedRefresh",s).MakeGenericMethod(stateType);var refresh=function.Invoke(null,null);return Call("RunFlow",options,interactive,before,(Func<bool>)Confirm,(Func<int>)Install,refresh,(Action<string>)(x=>{}));}static Func<T> GetTypedRefresh<T>(){return ()=>{refreshed++;return (T)next;};}
 static int Main(string[]a){Console.OutputEncoding=new UTF8Encoding(false);try{var asm=Assembly.LoadFrom(a[0]);runtime=asm.GetType("RuntimePrerequisite");stateType=asm.GetType("VcRuntimeState");optionsType=asm.GetType("InstallOptions");asm.GetType("L").GetMethod("Initialize",s).Invoke(null,new object[]{"en"});string required=(string)runtime.GetField("ValidatedVersion",s).GetRawConstantValue();
 Check(!(bool)Call("Selected",Options(false,false)),"localization alone skips prerequisite");Check((bool)Call("Selected",Options(true,false)),"MarkerPatch alone requires prerequisite");Check((bool)Call("Selected",Options(false,true)),"DLC alone requires prerequisite even without Marker checkbox");Check((bool)Call("Selected",Options(true,true)),"combined selection requires one shared prerequisite");
 Check(!(bool)Call("VersionReady",new object[]{null}),"missing version refused");Check(!(bool)Call("VersionReady","garbage"),"malformed version refused");Check(!(bool)Call("VersionReady","14.36.32532.0"),"reported old runtime triggers setup");Check((bool)Call("VersionReady",required),"bundled validated version accepted");Check((bool)Call("VersionReady","14.52.1.0"),"newer runtime accepted without downgrade");
 object old=State("14.36.32532.0"),good=State(required);Check(Ready(good),"both matching x86 components and UCRT ready");Set(good,"MsvcpX86",false);Check(!Ready(good),"x64/present version alone cannot satisfy x86");Set(good,"MsvcpX86",true);Set(good,"UcrtX86",false);Check(!Ready(good),"missing UCRT fails readiness");Set(good,"UcrtX86",true);Set(good,"VcruntimeVersion","14.36.0.0");Check(!Ready(good),"mixed new/old components trigger repair");good=State(required);
 Reset(good);Flow(Options(false,false),true,old);Check(asked==0&&installed==0&&refreshed==0,"Chinese-only never prompts or runs setup");Reset(good);Flow(Options(false,true),true,good);Check(asked==0&&installed==0,"current runtime never prompts");
 Reset(good,false);Check(Throws(()=>Flow(Options(false,true),true,old),typeof(OperationCanceledException)),"player decline cancels before game phase");Check(asked==1&&installed==0,"decline never launches setup");Reset(good);Check(Throws(()=>Flow(Options(true,false),false,old),typeof(InvalidOperationException)),"silent CLI refuses unmet dependency without hidden setup");Check(asked==0&&installed==0,"silent failure has no UI or setup call");
 Reset(good);Check(Ready(Flow(Options(false,true),true,old)),"successful setup rechecks readiness");Check(asked==1&&installed==1&&refreshed==1,"shared dependency invokes exactly one consent/setup/recheck");Reset(old);Check(Throws(()=>Flow(Options(true,false),true,old),typeof(InvalidOperationException)),"exit zero cannot bypass failed recheck");
 foreach(int code in new[]{1602,3010,1641}){Reset(good,true,code);Check(Throws(()=>Flow(Options(true,false),true,old),typeof(OperationCanceledException)),"cancel/reboot prevents game install: "+code);Check(refreshed==0,"reboot/cancel does not continue: "+code);}
 Reset(good,true,1603);Check(Throws(()=>Flow(Options(true,false),true,old),typeof(InvalidOperationException)),"setup failure prevents continuation");Reset(good,true,1638);Check(Ready(Flow(Options(true,false),true,old)),"newer-already-installed result requires successful recheck");Reset(old,true,1638);Check(Throws(()=>Flow(Options(true,false),true,old),typeof(InvalidOperationException)),"newer result does not excuse incomplete runtime");
 Check((int)Call("CanonicalExitCode",unchecked((int)0x80070666))==1638,"HRESULT product-version normalized");Check((int)Call("CanonicalExitCode",3010)==3010,"restart code retained");Check((int)Call("VerifyTrust",a[1])==0,"Microsoft setup passes native WinVerifyTrust");Check((bool)Call("ValidateInstaller",a[1]),"bundled Microsoft setup passes hash size signature publisher");string fake=Path.Combine(Path.GetDirectoryName(a[0]),"unsigned-test.txt");File.WriteAllText(fake,"not executable");Check(!(bool)Call("ValidateInstaller",fake),"untrusted wrong input rejected without execution");
 var actual=Call("Probe");Check(Ready(actual),"read-only probe recognizes local x86 runtime");string text="MarkerPatch 和 Severed DLC 共用必需的 Microsoft Visual C++ v14（x86／32 位）运行库。\r\n检测到未安装、版本较旧或文件不完整。是否打开微软官方安装程序？完成后将重新检查，再继续安装。";string translated=(string)asm.GetType("L").GetMethod("T",s).Invoke(null,new object[]{text});Check(translated.StartsWith("MarkerPatch and Severed DLC require"),"runtime consent message fully translated");
 Console.WriteLine("ALL RUNTIME PREREQUISITE CHECKS PASSED "+n);return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
